<?php declare(strict_types=1);require_once __DIR__.'/../lib/app_layout.php';require_once __DIR__.'/../lib/module_helpers.php';$user=require_role(['admin','principal','teacher']);$sid=(int)$user['school_id'];$pdo=db();$classes=school_classes($sid);$classId=(int)($_GET['class_id']??$_POST['class_id']??($classes[0]['id']??0));if($_SERVER['REQUEST_METHOD']==='POST'&&valid_csrf($_POST['csrf']??null)&&in_array($user['role'],['admin','principal'],true)){ $name=trim((string)$_POST['name']);if($name!==''){$p=$pdo->prepare('INSERT INTO subjects(school_id,class_id,name) VALUES(?,?,?)');$p->execute([$sid,$classId,$name]);flash_set('success','विषय जोडला.');header("Location:/modules/classes/subjects.php?class_id=$classId");exit;}}$c=$pdo->prepare('SELECT name FROM classes WHERE id=? AND school_id=?');$c->execute([$classId,$sid]);$class=$c->fetch();$s=$pdo->prepare('SELECT * FROM subjects WHERE school_id=? AND class_id=? ORDER BY id');$s->execute([$sid,$classId]);layout_start('विषय व्यवस्थापन','classes');?><div class="flex flex-wrap gap-3 mb-5"><?php foreach($classes as $item):?><a class="rounded-xl px-4 py-2 <?=$item['id']===$classId?'bg-navy text-white':'bg-white border text-navy'?>" href="?class_id=<?=$item['id']?>"><?=e($item['name'])?></a><?php endforeach;?></div><div class="bg-white border rounded-2xl p-6 max-w-2xl"><h2 class="text-xl font-bold text-navy"><?=e($class['name']??'वर्ग')?></h2><div class="flex flex-wrap gap-2 my-5"><?php foreach($s as $sub):?><span class="bg-pagebg rounded-lg px-3 py-2"><?=e($sub['name'])?></span><?php endforeach;?></div><?php if(in_array($user['role'],['admin','principal'],true)):?><form method="post" class="flex gap-2"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="class_id" value="<?=$classId?>"><input required name="name" placeholder="नवीन विषय" class="flex-1"><button class="bg-gold rounded-xl px-4 font-bold">जोडा</button></form><?php endif;?></div><?php layout_end();?>
